"""One separate run-only setup diagnostic of exact generated bytes, no retiming/acceptance."""
import argparse
from datetime import datetime, timezone
from pathlib import Path
import traceback
from kernel_optimizer.config import load_config
from kernel_optimizer.project.branches import fork_run
from kernel_optimizer.project.search import ProjectSearch
from kernel_optimizer.runtime.execution import write_json
from kernel_optimizer.runtime.provenance import framework_source
from scripts.experiments.v6_audit_fsdp_20261028 import read, sha
from scripts.experiments.v6_ddp_semantics_20261027 import disk_observation


def main(args):
    config = load_config(args.config, [])
    parent = ProjectSearch(config, args.parent / 'qwen-fixed')
    terminal = read(args.parent / 'followup-completed.json')
    assert terminal['phase'] == 'completed' and terminal['results']['C']['valid_run']
    identity = read(args.parent / 'staged-identities.json')
    candidate = parent.revisions.revision(identity['candidate']['id'])
    assert parent.revisions.current().id == identity['baseline']['id']
    frozen = read(args.parent / 'protocol.json')['frozen_identities'].copy()
    for p in [args.parent / 'C-result.json', args.parent / 'followup-completed.json', parent.output / 'project/current.json']:
        frozen[str(p)] = sha(p)
    assert all(sha(p) == h for p, h in frozen.items())
    args.output.mkdir(parents=True, exist_ok=True); assert not (args.output / 'protocol.json').exists()
    write_json(args.output / 'protocol.json', {'at': datetime.now(timezone.utc).isoformat(),
        'core': framework_source(), 'parent': str(args.parent), 'revision': candidate.id,
        'request': parent.request.portable(), 'frozen_identities': frozen,
        'scope': 'One separate existing candidate_diagnostics invocation to expose caught setup failure behind 62 observed fallback routes. Exact generated bytes/parameters/current-device request; no observe/compare, clean retiming, new candidate, search or acceptance. Fixed quality remains earlier result.'})
    write_json(args.output / 'state.json', {'phase': 'running', 'stage': 'setup_diagnostic'})
    result = {}
    try:
        branch = args.output / 'qwen-diagnostic'
        fork_run(parent.output, branch, revision_id=parent.revisions.current().id)
        search = ProjectSearch(config, branch)
        run = search.execute(candidate, 'setup-diagnostic', 'candidate_diagnostics')
        write_json(args.output / 'diagnostic-result.json', run)
        result['diagnostic'] = {'status': 'attempt_completed', 'worker_status': run['status'],
            'path': str(args.output / 'diagnostic-result.json'), 'sha256': sha(args.output / 'diagnostic-result.json')}
        assert search.revisions.current().id == parent.revisions.current().id
    except Exception:
        result['diagnostic'] = {'status': 'error', 'traceback': traceback.format_exc()}
    same = all(sha(p) == h for p, h in frozen.items())
    result['preservation'] = {'status': 'passed' if same else 'failed', 'files': len(frozen)}
    final = {'phase': 'completed' if same and result['diagnostic']['status'] == 'attempt_completed' else 'completed_with_errors',
        'finished_at': datetime.now(timezone.utc).isoformat(), 'results': result, 'disk': disk_observation(Path('/root/autodl-tmp'))}
    write_json(args.output / 'followup-results.json', result)
    write_json(args.output / 'state.json', final); write_json(args.output / 'followup-completed.json', final)


if __name__ == '__main__':
    p = argparse.ArgumentParser(__doc__)
    for n in ['parent', 'output', 'config']: p.add_argument('--' + n, type=Path, required=True)
    main(p.parse_args())
